{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Blend 80% baseline BCE with 20% pairwise softplus loss to improve candidate ordering using the same sampled pairs and valid-position mask. Preserve architecture, inference, sampling and training settings.",
      "edits": [
        {
          "find": "            loss = bce_criterion(pos_logits[indices], pos_labels)\n            loss = loss + bce_criterion(neg_logits[indices], neg_labels)",
          "replace": "            prediction_loss = bce_criterion(pos_logits[indices], pos_labels)\n            prediction_loss = prediction_loss + bce_criterion(neg_logits[indices], neg_labels)\n            pairwise_loss = torch.nn.functional.softplus(\n                neg_logits[indices] - pos_logits[indices]\n            ).mean()\n            loss = 0.8 * prediction_loss + 0.2 * pairwise_loss"
        }
      ]
    }
  ],
  "change_summary": "Apply the requested BCE/pairwise objective blend to each category's single SASRec model. No predictor changes are required."
}
